import 'package:flutter/material.dart';
void main()=>runApp(const ProductGalleryApp());
class ProductGalleryApp extends StatelessWidget { const ProductGalleryApp({super.key}); @override Widget build(BuildContext context)=>const MaterialApp(debugShowCheckedModeBanner:false,home:ProductGalleryScreen()); }
class Product { final String id,name,image; const Product(this.id,this.name,this.image); }
const products=[Product('p1','Headphones','https://images.unsplash.com/photo-1505740420928-5e560c06d30e'),Product('p2','Watch','https://images.unsplash.com/photo-1523275335684-37898b6baf30'),Product('p3','Camera','https://images.unsplash.com/photo-1516035069371-29a1b244cc32')];
class ProductGalleryScreen extends StatelessWidget { const ProductGalleryScreen({super.key}); @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Product Gallery')),body:GridView.count(crossAxisCount:2,children:[for(final p in products)InkWell(onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>ProductDetailsScreen(product:p))),child:Card(child:Column(children:[Expanded(child:Hero(tag:p.id,child:Image.network(p.image,fit:BoxFit.cover,width:180,errorBuilder:(_,__,___)=>const Icon(Icons.shopping_bag,size:60)))),Padding(padding:const EdgeInsets.all(8),child:Text(p.name))])))])); }
class ProductDetailsScreen extends StatelessWidget { final Product product; const ProductDetailsScreen({super.key,required this.product}); @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(product.name)),body:Center(child:Hero(tag:product.id,child:Image.network(product.image,fit:BoxFit.contain,errorBuilder:(_,__,___)=>const Icon(Icons.shopping_bag,size:120))))); }
